// Client Script for Bed Sampling Form
frappe.ui.form.on("Bed Sampling Form", {
    refresh: function (frm) {
        console.log("✅ Bed Sampling script loaded for:", frm.doc.name);

        // Avoid duplicate buttons
        try { frm.clear_custom_buttons(); } catch (e) { console.warn("clear_custom_buttons failed", e); }

        // Add "Add Variety" button
        frm.add_custom_button(__('Add Sample'), function () {
            console.log("🔘 Add Sample clicked");

            // Create dialog with variety + table
            let d = new frappe.ui.Dialog({
                title: "Add Sample Sampling",
                fields: [
                    {
                        label: "Variety",
                        fieldname: "variety",
                        fieldtype: "Link",
                        options: "Item",
                        reqd: 1
                    },
                    {
                        fieldname: "rows",
                        fieldtype: "Table",
                        label: "Sampling Rows",
                        cannot_add_rows: 0,
                        in_place_edit: true,
                        reqd: 1,
                        fields: [
                            { label: "Bed No.", fieldname: "bed_no", fieldtype: "Int", in_list_view: 1, reqd: 1 },
                            { label: "Rice Stage", fieldname: "rice_stage", fieldtype: "Int", in_list_view: 1 },
                            { label: "Ball Stage", fieldname: "ball_stage", fieldtype: "Int", in_list_view: 1 },
                            { label: "Colour Break Stage", fieldname: "colour_break_stage", fieldtype: "Int", in_list_view: 1 },
                            { label: "Full Colour Break Stage", fieldname: "full_colour_break_stage", fieldtype: "Int", in_list_view: 1 }
                        ]
                    }
                ],
                primary_action_label: "Add",
                primary_action(values) {
                    console.log("📥 Dialog values:", values);

                    if (!values.variety || !values.rows || values.rows.length === 0) {
                        frappe.msgprint("Please select a variety and add at least one row.");
                        return;
                    }

                    // Insert rows into child table
                    values.rows.forEach(r => {
                        let newrow = frm.add_child("growth_stages");
                        frappe.model.set_value(newrow.doctype, newrow.name, "crop_variety", values.variety);
                        frappe.model.set_value(newrow.doctype, newrow.name, "bed_no", r.bed_no);
                        frappe.model.set_value(newrow.doctype, newrow.name, "rice_stage", r.rice_stage || 0);
                        frappe.model.set_value(newrow.doctype, newrow.name, "ball_stage", r.ball_stage || 0);
                        frappe.model.set_value(newrow.doctype, newrow.name, "colour_break_stage", r.colour_break_stage || 0);
                        frappe.model.set_value(newrow.doctype, newrow.name, "full_colour_break_stage", r.full_colour_break_stage || 0);
                    });

                    frm.refresh_field("growth_stages");
                    frappe.msgprint(__("{0} row(s) added for variety {1}", [values.rows.length, values.variety]));
                    console.log("✅ Added", values.rows.length, "rows for variety", values.variety);

                    d.hide();
                }
            });

            d.show();
        });

        console.log("🚀 Add Sample button is visible in header");
    }
});

frappe.ui.form.on("Bed Sampling Form", {
    onload: function(frm) {
        // set the greenhouse filter immediately
        set_greenhouse_filter(frm);
    },

    custom_farm: function(frm) {
        // When Farm changes, reset both greenhouse & variety
        frm.set_value("greenhouse", "");
        frm.set_value("variety", "");
        set_greenhouse_filter(frm);
    },

    greenhouse: function(frm) {
        // When Greenhouse changes, clear variety and then load allowed varieties
        frm.set_value("variety", "");
        if (frm.doc.custom_farm && frm.doc.greenhouse) {
            set_variety_filter(frm);
        }
    }
});

/* ---------- Helpers ---------- */

function set_greenhouse_filter(frm) {
    frm.set_query("greenhouse", function() {
        return {
            filters: {
                warehouse_type: "Greenhouse",
                custom_farm: frm.doc.custom_farm
            }
        };
    });
}

function set_variety_filter(frm) {
    // make sure the 'variety' field is actually present
    if (!frm.fields_dict || !frm.fields_dict.variety) return;

    frappe.db.get_doc("Warehouse", frm.doc.greenhouse)
        .then(doc => {
            const varieties = (doc.custom_varieties_planted || [])
                .map(r => (r.variety || "").trim())
                .filter(Boolean);

            if (!varieties.length) {
                frappe.msgprint("No varieties listed for this greenhouse.");
                return;
            }

            if (varieties.length === 1) {
                // auto–select if only one variety
                frm.set_value("variety", varieties[0]);
                frm.set_query("variety", () => ({
                    filters: { name: ["=", varieties[0]] }
                }));
                return;
            }

            // otherwise show only those varieties to choose from
            frm.set_query("variety", () => ({
                filters: { name: ["in", varieties] }
            }));
        })
        .catch(err => {
            console.error("Error loading Warehouse:", err);
            frappe.msgprint("Could not load greenhouse varieties.");
        });
}

frappe.ui.form.on('Production Plan Form', {
    refresh: function(frm) {
        frm.trigger("toggle_child_tables");
    },

    // react to plan type changes (use actual fieldname)
    custom_plan_type: function(frm) {
        frm.trigger("toggle_child_tables");
        if ((frm.doc.custom_plan_type || "").toLowerCase() === "greenhouse operations") {
            frm.trigger("load_greenhouse_tasks");
        }
    },

    // actual greenhouse field name from your list
    greenhouses: function(frm) {
        if ((frm.doc.custom_plan_type || "").toLowerCase() === "greenhouse operations") {
            frm.trigger("load_greenhouse_tasks");
        }
    },

    week_no: function(frm) {
        if ((frm.doc.custom_plan_type || "").toLowerCase() === "greenhouse operations") {
            frm.trigger("load_greenhouse_tasks");
        }
    },

    toggle_child_tables: function(frm) {
        // actual child table fieldnames
        const GH_TBL = "custom_greenhouse_operations_task";
        const IRR_TBL = "custom_irrigation_task";
        const CP_TBL = "custom_crop_protection_task";

        // hide all first
        frm.set_df_property(GH_TBL, "hidden", 1);
        frm.set_df_property(IRR_TBL, "hidden", 1);
        frm.set_df_property(CP_TBL, "hidden", 1);

        const plan = (frm.doc.custom_plan_type || "").toLowerCase();
        if (plan === "greenhouse operations") {
            frm.set_df_property(GH_TBL, "hidden", 0);
        } else if (plan === "irrigation") {
            frm.set_df_property(IRR_TBL, "hidden", 0);
        } else if (plan === "crop protection") {
            frm.set_df_property(CP_TBL, "hidden", 0);
        }
    },

    load_greenhouse_tasks: function(frm) {
        // require greenhouse (note actual fieldname 'greenhouses') and week_no
        if (!(frm.doc.greenhouses && frm.doc.week_no)) return;

        const TARGET_TABLE = "custom_greenhouse_operations_task";

        // clear table
        frm.clear_table(TARGET_TABLE);
        frm.refresh_field(TARGET_TABLE);

        // avoid duplicates
        const seen = new Set();

        // helper: match possible greenhouse fields on task rows (some child tables might use 'greenhouse' or 'greenhouses' or 'warehouse')
        function matchesGreenhouse(t) {
            const tg = t.greenhouse || t.greenhouses || t.warehouse || t.location || "";
            return String(tg) === String(frm.doc.greenhouses);
        }

        function addTaskToTarget(task) {
            const key = `${task.day || ""}||${task.assigned_task || ""}`;
            if (seen.has(key)) return;
            seen.add(key);

            const row = frm.add_child(TARGET_TABLE);
            // copy common fields (adjust if your child doctype uses different fieldnames)
            row.day = task.day;
            row.assigned_task = task.assigned_task;
            row.purpose = task.purpose;
            row.target = task.target;
            row.actual = task.actual;
            row.achievement = task.achievement;
            row.supervisor_remarks = task.supervisor_remarks;

            // set flag if the child DocType has this field; safe if it doesn't exist
            try {
                if (row.hasOwnProperty("is_prepopulated")) row.is_prepopulated = 1;
            } catch (e) {} // ignore if property not present
        }

        function postprocessGrid() {
            frm.refresh_field(TARGET_TABLE);

            const grid = frm.fields_dict[TARGET_TABLE] && frm.fields_dict[TARGET_TABLE].grid;
            if (!grid) return;

            grid.grid_rows.forEach(grid_row => {
                // check both persisted flag and just-set flag
                if (grid_row.doc.is_prepopulated || grid_row.doc.is_prepopulated === 1) {
                    try {
                        grid_row.toggle_editable(false);
                        $(grid_row.row).find(".grid-delete-row").hide();
                        $(grid_row.row).addClass("highlight-prepopulated");
                    } catch (e) {
                        // ignore any UI errors
                    }
                }
            });
        }

        function copy_tasks(tasks) {
            (tasks || []).forEach(t => {
                if (matchesGreenhouse(t)) addTaskToTarget(t);
            });
            postprocessGrid();
        }

        // helper to get child table from a returned plan doc with fallbacks
        function getChildTableFromDoc(doc, preferredName, fallbackName) {
            return doc && (doc[preferredName] || doc[fallbackName] || []);
        }

        // Fetch Irrigation plans for this week (use real plan type field name)
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Production Plan Form",
                filters: {
                    custom_plan_type: "Irrigation",
                    week_no: frm.doc.week_no
                },
                fields: ["name"]
            },
            callback: function(r) {
                if (r.message && r.message.length) {
                    r.message.forEach(plan => {
                        frappe.call({
                            method: "frappe.client.get",
                            args: { doctype: "Production Plan Form", name: plan.name },
                            callback: function(res) {
                                if (res.message) {
                                    // try both possible child-table keys
                                    const tasks = getChildTableFromDoc(res.message, "custom_irrigation_task", "irrigation_task");
                                    copy_tasks(tasks);
                                }
                            },
                            error: function(err) {
                                console.warn("Irrigation plan not found:", plan.name, err);
                            }
                        });
                    });
                }
            },
            error: function(err) {
                console.warn("Error fetching irrigation plans", err);
            }
        });

        // Fetch Crop Protection plans for this week
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Production Plan Form",
                filters: {
                    custom_plan_type: "Crop Protection",
                    week_no: frm.doc.week_no
                },
                fields: ["name"]
            },
            callback: function(r) {
                if (r.message && r.message.length) {
                    r.message.forEach(plan => {
                        frappe.call({
                            method: "frappe.client.get",
                            args: { doctype: "Production Plan Form", name: plan.name },
                            callback: function(res) {
                                if (res.message) {
                                    const tasks = getChildTableFromDoc(res.message, "custom_crop_protection_task", "crop_protection_task");
                                    copy_tasks(tasks);
                                }
                            },
                            error: function(err) {
                                console.warn("Crop protection plan not found:", plan.name, err);
                            }
                        });
                    });
                }
            },
            error: function(err) {
                console.warn("Error fetching crop protection plans", err);
            }
        });
    }
});

// ensure child rows get highlighted even when rendered later
frappe.ui.form.on("Production Plan Task", {
    onload_post_render: function(frm, cdt, cdn) {
        const row = locals[cdt] && locals[cdn];
        if (!row) return;

        // find matching grid by actual fieldname
        const grid = cur_frm.fields_dict.custom_greenhouse_operations_task && cur_frm.fields_dict.custom_greenhouse_operations_task.grid;
        if (!grid) return;

        const grid_row = grid.get_row(cdn);
        if (grid_row && (row.is_prepopulated || row.is_prepopulated === 1)) {
            $(grid_row.row).addClass("highlight-prepopulated");
            try {
                grid_row.toggle_editable(false);
                $(grid_row.row).find(".grid-delete-row").hide();
            } catch (e) {}
        }
    }
});

// Add custom style
frappe.dom.set_style(`
    .highlight-prepopulated {
        background-color: #fff3cd !important; /* light yellow */
    }
`);

frappe.ui.form.on("Crop Cycle", {
    refresh(frm) {
        // recalc when form refreshes
        calculate_total_area(frm);
    },
    start_bed(frm) {
        regenerate_rows(frm);
    },
    end_bed(frm) {
        regenerate_rows(frm);
    },
    bed_length(frm) {
        update_child_dimensions(frm);
    },
    bed_width(frm) {
        update_child_dimensions(frm);
    },
    variety(frm) {
        // ✅ When parent variety changes,
        //    push the same value to each child row
        update_child_variety(frm);
    }
});

frappe.ui.form.on("Bed Number", {
    bed_length(frm, cdt, cdn) {
        update_row_area(cdt, cdn);
        calculate_total_area(frm);
    },
    bed_width(frm, cdt, cdn) {
        update_row_area(cdt, cdn);
        calculate_total_area(frm);
    }
});

// ----------------- Helpers -----------------

function regenerate_rows(frm) {
    let start = cint(frm.doc.start_bed);
    let end   = cint(frm.doc.end_bed);
    if (start && end && end >= start) {
        frm.clear_table("bed_numbers");
        for (let i = start; i <= end; i++) {
            let row = frm.add_child("bed_numbers");
            row.bed_no = i;
            if (frm.doc.bed_length) row.bed_length = frm.doc.bed_length;
            if (frm.doc.bed_width)  row.bed_width  = frm.doc.bed_width;
            if (frm.doc.variety)    row.variety_grown = frm.doc.variety;   // ✅ correct fieldname
            if (frm.doc.bed_length && frm.doc.bed_width) {
                row.bed_area = frm.doc.bed_length * frm.doc.bed_width;
            }
        }
        frm.refresh_field("bed_numbers");
        calculate_total_area(frm);
    }
}

function update_child_dimensions(frm) {
    (frm.doc.bed_numbers || []).forEach(function(row) {
        if (frm.doc.bed_length)
            frappe.model.set_value(row.doctype, row.name, "bed_length", frm.doc.bed_length);
        if (frm.doc.bed_width)
            frappe.model.set_value(row.doctype, row.name, "bed_width", frm.doc.bed_width);
        update_row_area(row.doctype, row.name);
    });
    calculate_total_area(frm);
}

function update_child_variety(frm) {
    (frm.doc.bed_numbers || []).forEach(function(row) {
        if (frm.doc.variety) {
            // ✅ push parent variety to child field `variety_grown`
            frappe.model.set_value(row.doctype, row.name, "variety_grown", frm.doc.variety);
        }
    });
}

function update_row_area(cdt, cdn) {
    let row = locals[cdt][cdn];
    let l = flt(row.bed_length);
    let w = flt(row.bed_width);
    frappe.model.set_value(cdt, cdn, "bed_area", (l && w) ? l * w : 0);
}

function calculate_total_area(frm) {
    let total = 0;
    (frm.doc.bed_numbers || []).forEach(function(r) {
        total += flt(r.bed_area);
    });
    frm.set_value("total_beds_area", total);
}

