frappe.ui.form.on("Production Projection", {
    refresh(frm) {
        set_actual_harvest(frm);
    },
    after_save(frm) {
        set_actual_harvest(frm);
    }
});

function set_actual_harvest(frm) {
    // loop through each projection week row
    (frm.doc.projection_week || []).forEach(row => {
        // extract week number from text e.g. "Week 38"
        let week_txt = (row.week_no || "").toLowerCase().replace("week", "").trim();
        let iso_week = cint(week_txt);
        if (!iso_week) return;

        frappe.call({
            method: "production_projection",
            args: {
                greenhouse: frm.doc.greenhouse,
                crop_variety: frm.doc.crop_variety,
                year: frm.doc.year,
                week_no: iso_week
            },
            callback: function(r) {
                if (r.message != null) {
                    frappe.model.set_value(row.doctype, row.name,
                        "actual_harvest", r.message);
                }
            }
        });
    });
}

frappe.ui.form.on("Bed Sampling Form", {
    onload: function(frm) {
        set_greenhouse_filter(frm);
        set_child_bed_filter(frm);
    },

    custom_farm: function(frm) {
        // Reset when farm changes
        frm.set_value("greenhouse", "");
        frm.set_value("variety", "");
        frm.set_value("bed_no", "");

        set_greenhouse_filter(frm);
        set_child_bed_filter(frm);
    },

    greenhouse: function(frm) {
        // Reset when greenhouse changes
        frm.set_value("variety", "");
        frm.set_value("bed_no", "");

        if (frm.doc.custom_farm && frm.doc.greenhouse) {
            set_variety_filter(frm);
            set_bed_filter(frm);       
            set_child_bed_filter(frm); 
        }
    },

    refresh: function(frm) {
        // 🔒 Lock fields once child rows exist
        if (frm.doc.growth_stages && frm.doc.growth_stages.length > 0) {
            frm.set_df_property("variety", "read_only", 1);
            frm.set_df_property("greenhouse", "read_only", 1);
            frm.set_df_property("custom_farm", "read_only", 1);
        } else {
            frm.set_df_property("variety", "read_only", 0);
            frm.set_df_property("greenhouse", "read_only", 0);
            frm.set_df_property("custom_farm", "read_only", 0);
        }
    },

    // ✅ Auto-pick ISO week number when sampling date is selected
    date: function(frm) {
        if (!frm.doc.date) return;

        const date_obj = frappe.datetime.str_to_obj(frm.doc.date);

        // --- ISO Week Calculation ---
        const tempDate = new Date(date_obj.valueOf());

        // ISO: Monday = 0, Sunday = 6
        const dayNr = (date_obj.getDay() + 6) % 7;
        tempDate.setDate(tempDate.getDate() - dayNr + 3);

        // First Thursday of the year
        const firstThursday = new Date(tempDate.getFullYear(), 0, 4);

        // Week number
        const weekNo = 1 + Math.round(
            ((tempDate - firstThursday) / 86400000 - 3 + ((firstThursday.getDay() + 6) % 7)) / 7
        );

        // Set ISO week_no field
        frm.set_value("week_no", weekNo);

        // Optional: set ISO year
        frm.set_value("sampling_year", tempDate.getFullYear());

        frappe.msgprint(`📅 Sampling Date: ${frm.doc.date} → ISO Week ${weekNo}, ${tempDate.getFullYear()}`);
    }
});

/* ---------- Child Table Events ---------- */
frappe.ui.form.on("Sampling Table", {
    bed_no: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.bed_no) {
            frappe.db.get_doc("Bed", row.bed_no).then(bed => {
                // ✅ Fetch total_variety_area into child row
                frappe.model.set_value(cdt, cdn, "total_variety_area", bed.total_variety_area);

                // ✅ Set parent area_covered_by_variety (same for all beds of that variety)
                if (!frm.doc.area_covered_by_variety) {
                    frm.set_value("area_covered_by_variety", bed.total_variety_area);
                }
            });
        }
    }
});

/* ---------- Helpers ---------- */

// Parent form: Greenhouse filter
function set_greenhouse_filter(frm) {
    frm.set_query("greenhouse", function() {
        return {
            filters: {
                warehouse_type: "Greenhouse",
                custom_farm: frm.doc.custom_farm
            }
        };
    });
}

// Parent form: Variety filter
function set_variety_filter(frm) {
    if (!frm.fields_dict || !frm.fields_dict.variety) return;

    frappe.db.get_doc("Warehouse", frm.doc.greenhouse)
        .then(doc => {
            const varieties = (doc.custom_varieties_planted || [])
                .map(r => (r.variety || "").trim())
                .filter(Boolean);

            if (!varieties.length) {
                frappe.msgprint("No varieties listed for this greenhouse.");
                return;
            }

            if (varieties.length === 1) {
                frm.set_value("variety", varieties[0]);
                frm.set_query("variety", () => ({ filters: { name: ["=", varieties[0]] } }));
                return;
            }

            frm.set_query("variety", () => ({ filters: { name: ["in", varieties] } }));
        })
        .catch(err => {
            console.error("Error loading Warehouse:", err);
            frappe.msgprint("Could not load greenhouse varieties.");
        });
}

// Parent form: Bed filter (if you still need bed_no on parent)
function set_bed_filter(frm) {
    if (frm.fields_dict.bed_no) {
        frm.set_query("bed_no", function() {
            return {
                filters: { greenhouse: frm.doc.greenhouse }
            };
        });
    }
}

// Child table: bed_no filter → by parent greenhouse + variety
function set_child_bed_filter(frm) {
    if (frm.fields_dict.growth_stages) {
        frm.fields_dict.growth_stages.grid.get_field("bed_no").get_query = function(doc, cdt, cdn) {
            return {
                filters: {
                    greenhouse: frm.doc.greenhouse,
                    variety: frm.doc.variety
                }
            };
        };
    }
}

frappe.ui.form.on("Animal Event", {
    event_type: function(frm) {
        toggle_event_fields(frm);

        // When Service is first created, set pregnancy status = Pending
        if (frm.doc.event_type === "Service" && !frm.doc.pregnancy_confirmation_status) {
            frm.set_value("pregnancy_confirmation_status", "Pending");
        }
    },
    refresh: function(frm) {
        toggle_event_fields(frm);
    },
