frappe.ui.form.on('Production Projection', {
    crop_cycle: function(frm) {
        if (frm.doc.crop_cycle) {
            // Fetch crop cycle details when a crop cycle is selected
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Crop Cycle',
                    name: frm.doc.crop_cycle
                },
                callback: function(r) {
                    if (r.message) {
                        // Set the planting date and area from crop cycle
                        frm.set_value('date_of_planting', r.message.planting_date);
                        frm.set_value('area', r.message.total_beds_area);

                        // Optional: Also set the variety if not already set
                        if (!frm.doc.crop_variety && r.message.variety) {
                            frm.set_value('crop_variety', r.message.variety);
                        }
                    }
                }
            });
        }
    },

    // Also trigger when crop variety changes to find related crop cycles
    crop_variety: function(frm) {
        if (frm.doc.crop_variety && frm.doc.greenhouse) {
            // Find crop cycles with this variety and greenhouse
            find_matching_crop_cycle(frm);
        }
    },

    greenhouse: function(frm) {
        if (frm.doc.crop_variety && frm.doc.greenhouse) {
            // Find crop cycles with this variety and greenhouse
            find_matching_crop_cycle(frm);
        }
    }
});

function find_matching_crop_cycle(frm) {
    // If we already have a crop cycle selected, don't auto-select
    if (frm.doc.crop_cycle) return;

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Crop Cycle',
            filters: [
                ['variety', '=', frm.doc.crop_variety],
                ['greenhouse', '=', frm.doc.greenhouse],
                ['docstatus', '!=', 2] // Not cancelled
            ],
            fields: ['name', 'planting_date', 'total_beds_area'],
            order_by: 'creation desc',
            limit: 1
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                var crop_cycle = r.message[0];
                frm.set_value('crop_cycle', crop_cycle.name);
                frm.set_value('date_of_planting', crop_cycle.planting_date);
                frm.set_value('area', crop_cycle.total_beds_area);
            }
        }
    });
}

